<?php
namespace KaarBooking\Component\KaarBooking\Administrator\Controller;defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\CMS\MVC\Controller\BaseController;use Joomla\CMS\Router\Route;use Joomla\CMS\Session\Session;use KaarBooking\Component\KaarBooking\Administrator\Service\MediaUploadService;
final class DriversController extends BaseController{public function save():void{Session::checkToken('post')or jexit('Invalid token');$user=$this->app->getIdentity();if(!$user->authorise('core.create','com_kaarbooking'))throw new \RuntimeException('Not authorised',403);$name=trim((string)$this->input->post->getString('display_name',''));$licence=strtoupper(preg_replace('/[^A-Z0-9]/','',trim((string)$this->input->post->getString('licence_number',''))));if($name===''||strlen($licence)<5)throw new \DomainException('Driver name and a valid driving licence number are required.');$db=Factory::getContainer()->get(\Joomla\Database\DatabaseInterface::class);$userId=$this->input->post->getInt('user_id')?:null;$row=(object)['user_id'=>$userId,'company_id'=>$this->input->post->getInt('company_id')?:null,'licence_number_masked'=>'••••'.substr($licence,-4),'licence_number_hash'=>hash_hmac('sha256',$licence,(string)$this->app->get('secret')),'display_name'=>mb_substr($name,0,190),'phone_masked'=>mb_substr(trim($this->input->post->getString('phone')),0,32),'status'=>'pending','compliance_status'=>'pending','online_state'=>'offline','created'=>Factory::getDate()->toSql(),'modified'=>null];$db->insertObject('#__kaar_drivers',$row,'id');MediaUploadService::store($this->input->files->get('profile_image',[],'array'),'driver',(int)$row->id,(int)$user->id,1,1,'profile');$this->app->enqueueMessage('Driver added. Verify required documents before activation.','success');$this->setRedirect(Route::_('index.php?option=com_kaarbooking&view=drivers',false));}}


